mapper.select:
SELECT COUNT(*)
FROM weekly_work_schedule
WHERE employee_id = #{employeeId}

SELECT w.weekly_id as weeklyId, w.employee_id as employeeId, w.start_date as startDate, w.end_date as endDate, w.approval_status as approvalStatus, w.plan_date as planDate, w.work_form as workForm, w.schedule_title as scheduleTitle, w.memo as memo, w.reject_reason as rejectReason, e.employee_name as employeeName, COALESCE(o.org_name, '미소속') as departmentName, COALESCE(p.position_name, '직원') as positionName, w.created_at as createdAt, w.updated_at as updatedAt FROM weekly_work_schedule w JOIN employee e ON e.employee_id = w.employee_id LEFT JOIN employee_hr_info h ON h.employee_id = e.employee_id LEFT JOIN organization o ON o.org_id = h.org_id LEFT JOIN hr_position p ON p.position_id = h.position_id
w.approval_status = #{status}
ORDER BY w.start_date DESC, w.weekly_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT w.weekly_id as weeklyId, w.employee_id as employeeId, w.start_date as startDate, w.end_date as endDate, w.approval_status as approvalStatus, w.plan_date as planDate, w.work_form as workForm, w.schedule_title as scheduleTitle, w.memo as memo, w.reject_reason as rejectReason, e.employee_name as employeeName, COALESCE(o.org_name, '미소속') as departmentName, COALESCE(p.position_name, '직원') as positionName, w.created_at as createdAt, w.updated_at as updatedAt FROM weekly_work_schedule w JOIN employee e ON e.employee_id = w.employee_id LEFT JOIN employee_hr_info h ON h.employee_id = e.employee_id LEFT JOIN organization o ON o.org_id = h.org_id LEFT JOIN hr_position p ON p.position_id = h.position_id
w.approval_status = #{status}
AND
EXISTS ( SELECT 1 FROM employee_hr_info actor_h WHERE actor_h.employee_id = #{actorEmployeeId} AND actor_h.org_id = h.org_id )
ORDER BY w.start_date DESC, w.weekly_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT EXISTS (
    SELECT 1
    FROM weekly_work_schedule w
    JOIN employee_hr_info target_h ON target_h.employee_id = w.employee_id
    JOIN employee_hr_info actor_h ON actor_h.org_id = target_h.org_id
    WHERE actor_h.employee_id = #{actorEmployeeId}
      AND w.weekly_id = #{weeklyId}
)

SELECT COUNT(*)
FROM weekly_work_schedule
WHERE employee_id = #{employeeId}
  AND plan_date = #{planDate}
  AND approval_status IN ('PENDING', 'APPROVED')
  AND start_date <= #{endDate}
  AND end_date >= #{startDate}
